import {
  Group,
  Mesh,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  Color,
} from 'three/webgpu';
import {
  uv,
  texture,
  vec2,
  vec3,
  mix,
  smoothstep,
  uniform,
  fract,
  sin,
  dot,
  length,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { PointLight } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  const content = new Group();
  root.add(content);

  const cardWidth = 2.4;
  const cardHeight = 1.5;

  // ---- back plate (machined-metal frame, depth plane 1) ----
  const backGeo = new PlaneGeometry(cardWidth + 0.2, cardHeight + 0.2);
  const backMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  backMat.colorNode = mix(
    vec3(new Color(colors.surface).r, new Color(colors.surface).g, new Color(colors.surface).b),
    vec3(new Color(colors.ink).r, new Color(colors.ink).g, new Color(colors.ink).b),
    uv().y
  );
  const backPlate = new Mesh(backGeo, backMat);
  backPlate.position.set(0, 0, -0.05);
  content.add(backPlate);

  // ---- soft cast shadow (depth cue behind subject) ----
  const shadowGeo = new PlaneGeometry(cardWidth + 0.1, cardHeight + 0.1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const shadowDist = length(uv().sub(vec2(0.5, 0.5)));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = mix(0.45, 0.0, smoothstep(0.28, 0.5, shadowDist));
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0.06, -0.08, -0.03);
  content.add(shadowPlane);

  // ---- main card (subject, engineered gradient + grain, texture fades in) ----
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.58,
    metalness: 0.15,
  });

  const gradTop = new Color(colors.ink);
  const gradBottom = new Color(colors.surface);
  const gradNode = mix(
    vec3(gradBottom.r, gradBottom.g, gradBottom.b),
    vec3(gradTop.r, gradTop.g, gradTop.b),
    uv().y
  );

  const grainUv = uv().mul(90.0);
  const grain = fract(sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453));
  const grainNode = grain.sub(0.5).mul(0.035);

  cardMat.colorNode = gradNode.add(grainNode);

  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0.02);
  content.add(card);

  // ---- accent signal strip (small brightest accent, <=10% frame) ----
  const stripGeo = new PlaneGeometry(cardWidth * 0.86, 0.05);
  const stripMat = new MeshStandardNodeMaterial({
    roughness: 0.4,
    metalness: 0.2,
  });
  const accentColor = new Color(colors.accent);
  stripMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  stripMat.emissive = accentColor;
  stripMat.emissiveIntensity = 1.1;
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardHeight / 2 + 0.06, 0.04);
  content.add(strip);

  // ---- node-local rim/accent light ----
  const rimLight = new PointLight(colors.accent, 1.0, 6.0, 2.0);
  rimLight.position.set(-1.2, 0.8, 1.6);
  content.add(rimLight);

  // ---- texture load (async, cached) ----
  const fadeUniform = uniform(0);
  let loadedTexture = null;

  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      const texNode = texture(tex, uv());
      cardMat.colorNode = mix(
        gradNode.add(grainNode),
        texNode.rgb.add(grainNode),
        fadeUniform
      );
      cardMat.needsUpdate = true;
      gsap.to(fadeUniform, {
        value: 1,
        duration: 0.5,
        ease: 'power2.out',
      });
    })
    .catch(() => {});

  // ---- entrance motion (rise-in + weighted-settle), applied to inner content only ----
  content.position.y += 0.4;
  content.scale.setScalar(1.0);

  const tl = gsap.timeline();
  tl.to(content.position, {
    y: content.position.y - 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    content.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
      startAt: { x: 1.04, y: 1.04, z: 1.04 },
    },
    0.1
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(fadeUniform);

    backGeo.dispose();
    backMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();

    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    content.remove(rimLight);
    content.clear();
    root.clear();
  };

  return root;
}
